-- 요구사항이 하나 온다

// 모든 서비스 메서드의 실행 시간을 남겨 주세요

$ find src/main/java -name '*Service.java' | wc -l
       8
$ grep -c 'public ' src/main/java/study/adv/*Service.java | awk -F: '{s+=$2} END {print s}'
      34

--   서른네 곳이다


-- 손으로 넣어 본다

@Service
public class OrderService {
    public void order(String item) {
        long t0 = System.nanoTime();
        try {
            repository.save(item);
        } finally {
            log.info("order {} ms", (System.nanoTime() - t0) / 1_000_000);
        }
    }

    public void cancel(Long id) {
        long t0 = System.nanoTime();
        try {
            repository.delete(id);
        } finally {
            log.info("cancel {} ms", (System.nanoTime() - t0) / 1_000_000);
        }
    }
}

$ git diff --stat
 src/main/java/study/adv/OrderService.java   | 42 ++++++++++----
 src/main/java/study/adv/MemberService.java  | 38 +++++++++---
 ... 8 files changed, 214 insertions(+), 68 deletions(-)

--   214 줄이 늘었다


-- 본문을 빼내 본다

class TimeUtil {
    static <T> T measure(String name, Supplier<T> body) {
        long t0 = System.nanoTime();
        try {
            return body.get();
        } finally {
            log.info("{} {} ms", name, (System.nanoTime() - t0) / 1_000_000);
        }
    }
}

public void order(String item) {
    TimeUtil.measure("order", () -> { repository.save(item); return null; });
}

public void cancel(Long id) {
    TimeUtil.measure("cancel", () -> { repository.delete(id); return null; });
}

$ git diff --stat
 9 files changed, 76 insertions(+), 214 deletions(-)

$ grep -c 'TimeUtil.measure' src/main/java/study/adv/*Service.java \
    | awk -F: '{s+=$2} END {print s}'
      34

--   214 줄이 76 줄이 됐다
--   그런데 부르는 줄이 34 개 그대로다
--   이게 안 빠지는 중복이다


