--   경고도 없다


-- 목표는 이것이다

@Aspect
@Component
class TimeAspect {
    @Around("execution(* study.adv..*Service.*(..))")
    public Object around(ProceedingJoinPoint pjp) throws Throwable {
        long t0 = System.nanoTime();
        try {
            return pjp.proceed();
        } finally {
            log.info("{} {} ms", pjp.getSignature().getName(),
                     (System.nanoTime() - t0) / 1_000_000);
        }
    }
}

$ git checkout src/main/java/study/adv/
$ git diff --stat
